    name: 'Deadlift with Bands',
    primary: 'back',
    secondary: ['forearm', 'glutes', 'hamstrings', 'quads', 'trapezius'],
    equipment: 'Barbell',
    difficulty: 'Advanced',
    art: '',
    steps: [
