    name: 'Reverse Band Box Squat',
    primary: 'quads',
    secondary: ['glutes', 'calves', 'forearm', 'hamstrings', 'back'],
    equipment: 'Barbell',
    difficulty: 'Intermediate',
    art: '',
    steps: [
