  Exercise(
    id: 'kFDa5Y0',
    name: 'Seated Dumbbell Palms-Down Wrist Curl',
    primary: 'forearm',
    secondary: [],
    equipment: 'Dumbbell',
    difficulty: 'Beginner',
    art: '',
    steps: [
